import math


def parse_amount(text):
    value = text.strip().replace(',', '.')
    try:
        amount = float(value)
    except ValueError:
        raise ValueError('invalid amount')
    if amount < 0 or not math.isfinite(amount):
        raise ValueError('invalid amount')
    return amount
